17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
42	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final TelephoneNormalizer telephoneNormalizer;
69	
70	    private final HouseholdNormalizer householdNormalizer;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 TelephoneNormalizer telephoneNormalizer,
77	                                 HouseholdNormalizer householdNormalizer) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	        this.telephoneNormalizer = telephoneNormalizer;
83	        this.householdNormalizer = householdNormalizer;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        normalizeOwnerFields(owner);
117	        // Reject creating an owner whose normalized telephone is already used by another owner.
118	        String normalizedTelephone = owner.getTelephone();
119	        if (isTelephoneInUse(normalizedTelephone)) {
120	            throw new DuplicateTelephoneException(
121	                "An owner with telephone " + normalizedTelephone + " already exists");
122	        }
123	        // Identify any existing owners who share a household (same last name and address,
124	        // compared case-insensitively with collapsed whitespace) with the owner being created.
125	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
126	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
127	        // Reject creating an owner who shares a household with an existing owner, unless the
128	        // request explicitly opts in with 'sharesHousehold' true.
129	        if (!sharesHousehold && !householdMembers.isEmpty()) {
130	            throw new DuplicateHouseholdException(
131	                "An owner with the same last name and address already exists");
132	        }
133	        // When opting in and joining an existing household, assign the new owner and every
134	        // existing member the same stable household identifier derived from the last name and
135	        // address, so all owners of the household share one 'householdId'.
136	        if (sharesHousehold && !householdMembers.isEmpty()) {
137	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
138	            owner.setHouseholdId(householdId);
139	            for (Owner member : householdMembers) {
140	                if (!householdId.equals(member.getHouseholdId())) {
141	                    member.setHouseholdId(householdId);
142	                    this.clinicService.saveOwner(member);
143	                }
144	            }
145	        }
146	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
147	        // equal to one more than the current number of owners, fixed at creation time.
148	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    /**
157	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
158	     * persisted and returned in its canonical form. The telephone is normalized to E.164
159	     * (rejecting an unformattable value with 400), the email is lower-cased, and a missing
160	     * registration date defaults to the server's current date. Centralising these per-field
161	     * canonicalizations here keeps {@link #addOwner} focused on the duplicate, household and
162	     * customer-code rules.
163	     *
164	     * @param owner the newly mapped owner to canonicalize
165	     */
166	    private void normalizeOwnerFields(Owner owner) {
167	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
168	        // A value that cannot form a valid E.164 number is rejected with 400.
169	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
170	        // Store the (already syntactically validated) email lower-cased so it is persisted and
171	        // returned in canonical form. A missing email is left untouched.
172	        owner.setEmail(normalizeEmail(owner.getEmail()));
173	        // Default the registration date to the server's current date when the client did not
174	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
175	        if (owner.getRegistrationDate() == null) {
176	            owner.setRegistrationDate(java.time.LocalDate.now());
177	        }
178	    }
179	
180	    /**
181	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
182	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
183	     * syntactically valid address (rejecting anything else with 400).
184	     *
